// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        vm.assume(uint160(actor) > 10); // avoid precompile/system addresses (no EOA code there for origin spoof)
        // owner opens the contract (setUp made address(this) the owner)
        vm.prank(address(this));
        c.OpenToThePublic();
        // any actor (EOA, i.e. msg.sender == tx.origin) may now wager the betLimit (0) with 0 value
        vm.startPrank(actor, actor);
        bool ok;
        try c.wager{value: 0}() { ok = true; } catch { ok = false; }
        vm.stopPrank();
        assertTrue(ok && c.hasPlayerWagered(actor));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), 0);
    }

    function testFuzz_property(uint256 calls, address actor) public {
        vm.assume(calls >= 2 && calls <= 5);
        vm.assume(actor != address(0));

        for (uint256 i = 0; i < calls; i++) {
            c.OpenToThePublic();
        }

        // After any number of owner invocations of OpenToThePublic, the contract
        // must still be open to the public: a non-owner player with a wager must
        // be able to place a bet (wager succeeds only when openToPublic is true).
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.wager.selector));

        assertTrue(ok);
    }
}

