pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 /* seed */) public {
        // owner of c is address(this) (deployment msg.sender)
        vm.startPrank(address(this));
        c.OpenToThePublic();
        c.OpenToThePublic();
        vm.stopPrank();
        assertTrue(c.openToPublic());
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint256 amount) public {
        (bool ok, ) = address(c).call(abi.encodeWithSignature("AdjustBetAmounts(uint256)", amount));
        require(ok, "call failed (caller must be owner)");
        assert(c.currentBetLimit() == amount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function runTest(uint256 newAmount) public {
        uint256 before = c.currentBetLimit();
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature("AdjustBetAmounts(uint256)", newAmount)
        );
        assert(!ok && c.currentBetLimit() == before);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint256 newLimit) public {
        require(address(c).balance >= 0);
        uint256 bet0 = c.currentBetLimit();
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.AdjustBetAmounts.selector, newLimit));
        assert(!ok || c.currentBetLimit() == bet0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(true);
        uint256 before_ = c.currentBetLimit();
        bool reverted;
        try c.AdjustBetAmounts(amount) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.currentBetLimit() == before_);
    }
    receive() external payable {}
}

